Plan: Use a mutex and condition variable to protect the semaphore count and notify waiting threads.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int count=0;
static void *worker(void *p) {
    (void)p;
    for(int i=0;i<10;i++) {
        ck(pthread_mutex_lock(&m));
        assert(count<10);
        ++count;
        ck(pthread_cond_broadcast(&cv));
        ck(pthread_mutex_unlock(&m));
    }
    return NULL;
}
int main(void) {
    pthread_t t[2];
    for(int i=0;i<2;i++) ck(pthread_create(&t[i],NULL,worker,NULL));
    for(int i=0;i<2;i++) ck(pthread_join(t[i],NULL));
    assert(count==20);
    ck(pthread_cond_destroy(&cv));
    ck(pthread_mutex_destroy(&m));
    return 0;
}
```

Why it is correct: The mutex protects count and the condition variable broadcasts every increment. The broadcast is safe because every worker has a finite path to completion. The join waits for both threads before asserting the final count.

