static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int count=0;
static int custom_sem_wait(sem_t *s) {
    ck(pthread_mutex_lock(&m));
    if (--count<0) { pthread_mutex_unlock(&m); return -1; }
    ck(pthread_cond_broadcast(&cv)); ck(pthread_mutex_unlock(&m)); return 0;
}
static int custom_sem_trywait(sem_t *s) {
    ck(pthread_mutex_lock(&m));
    if (--count<0) { pthread_mutex_unlock(&m); return -1; }
    ck(pthread_cond_broadcast(&cv)); ck(pthread_mutex_unlock(&m)); return 0;
}
static void *worker(void *p) {
    (void)p;
    for(int i=0;i<10;i++) {
        int e=custom_sem_wait(&s); if (e) { fprintf(stderr,"worker %d wait failed\n",i); return NULL; }
        printf("worker %d acquired\n",i);
        for(int j=0;j<10;j++) { sleep(1); printf("worker %d busy\n",i); }
        custom_sem_trywait(&s); if (custom_sem_trywait(&s)==-1) { fprintf(stderr,"worker %d trywait failed\n",i); return NULL; }
        printf("worker %d released\n",i);
    }
    return NULL;
}
int main(void) {
    sem_t s=SEM_INITIALIZER;
    pthread_t t[2];
    ck(sem_init(&s,0,0));
    for(int i=0;i<2;i++) ck(pthread_create(&t[i],NULL,worker,NULL));
    for(int i=0;i<2;i++) ck(pthread_join(t[i],NULL));
    ck(sem_destroy(&s)); ck(pthread_cond_destroy(&cv)); ck(pthread_mutex_destroy(&m));
    printf("done\n");
    return 0;
}
```

Why it is correct: The mutex protects count and the condition variable. The worker uses the same entry section for both wait and trywait, so the broadcast is safe. The finite loop and finite workers prevent indefinite blocking. The finite join and cleanup ensure resources are released.

