        ckp(&m); o++; ckv(&m);
        ckp(&h); h-=2; ckv(&h); ckv(&o); o--; ckv(&m);
        ckp(&b); bond(); ckv(&b); ckp(&m); m=1; ckv(&m);
    } return NULL;
}
static void *hydrogen(void *p) {
    (void)p; for (int i=0;i<6;i++) {
        ckp(&m); h++; ckv(&m);
        ckp(&h); h-=2; ckv(&h); ckv(&o); o--; ckv(&m);
        ckp(&b); bond(); ckv(&b); ckp(&m); m=1; ckv(&m);
    } return NULL;
}
static sem_t m=1,b=0,o=0,h=0;
static pthread_t t[2];
int main(void) {
    pthread_create(&t[0],NULL,oxygen,NULL);
    pthread_create(&t[1],NULL,hydrogen,NULL);
    for (int i=0;i<2;i++) ck(pthread_join(t[i],NULL));
