static int buffer[5]={0},count=0;
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t empty=PTHREAD_COND_INITIALIZER,fill=PTHREAD_COND_INITIALIZER;
static void *producer(void *arg) {
    int i=*(int *)arg;
    for(int j=0;j<10;j++) {
        ckp(&empty);
        buffer[count]=j;
        count++;
        cks(&fill);
    } return NULL;
}
static void *consumer(void *arg) {
    int i=*(int *)arg;
    for(int j=0;j<10;j++) {
        ckp(&fill);
        int tmp=buffer[--count];
        cks(&empty);
        printf("consumer %d got %d\n",i,tmp);
    } return NULL;
}
int main(void) {
    pthread_t p[2],c[2];
    for(int i=0;i<2;i++) ck(pthread_create(&p[i],NULL,producer,&i));
    for(int i=0;i<2;i++) ck(pthread_create(&c[i],NULL,consumer,&i));
    for(int i=0;i<2;i++) ck(pthread_join(p[i],NULL));
    for(int i=0;i<2;i++) ck(pthread_join(c[i],NULL));
    ck(pthread_cond_destroy(&empty));
    ck(pthread_cond_destroy(&fill));
    ck(pthread_mutex_destroy(&m));
    printf("done\n"); return 0;
}
