Plan: Use a mutex and condition variable to protect the shared counter and its active-reader count. A writer must wait for all readers to finish before writing, and a new reader must wait for the current writer to finish before entering.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
static void ck(int e, const char *s) { if (e) { fprintf(stderr,"%s\n",s); exit(1); } }
#define CK(e) do { ck((e),#e); } while (0)
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int count=0, readers=0;
static void *reader(void *p) {
    (void)p; CK(pthread_mutex_lock(&m));
    while(readers==0) CK(pthread_cond_wait(&cv,&m));
    readers++;
    CK(pthread_mutex_unlock(&m));
    CK(pthread_mutex_lock(&m));
    count++;
    CK(pthread_mutex_unlock(&m));
    CK(pthread_mutex_lock(&m));
    readers--;
    if(readers==0) CK(pthread_cond_broadcast(&cv));
    CK(pthread_mutex_unlock(&m));
    return NULL;
}
static void *writer(void *p) {
    (void)p; CK(pthread_mutex_lock(&m));
    while(readers>0) CK(pthread_cond_wait(&cv,&m));
    CK(pthread_mutex_unlock(&m));
    CK(pthread_mutex_lock(&m));
    count++;
    CK(pthread_mutex_unlock(&m));
    return NULL;
}
int main(void) {
    pthread_t r[3],w[2];
    for(int i=0;i<3;i++) CK(pthread_create(&r[i],NULL,reader,NULL));
    for(int i=0;i<2;i++) CK(pthread_create(&w[i],NULL,writer,NULL));
    for(int i=0;i<3;i++) CK(pthread_join(r[i],NULL));
    for(int i=0;i<2;i++) CK(pthread_join(w[i],NULL));
    assert(count==5);
    pthread_cond_destroy(&cv); pthread_mutex_destroy(&m); return 0;
}
```

Why it is correct: The shared counter and its active-reader count are protected by m. A writer waits for readers to finish before writing, and a new reader waits for the current writer to finish before entering. The condition variable broadcasts when readers leave, so a waiting writer can proceed.

