Plan: Use a single semaphore initialized to zero for rendezvous; each thread waits before its loop iteration and signals after its loop iteration.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
static void cksem(int e) { if (e) { fprintf(stderr,"sem error %d\n",e); exit(1); } }
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static sem_t s;
static void *worker(void *p) {
    (void)p;
    for (int i=0;i<5;i++) {
        cksem(sem_wait(&s));
        printf("thread %d iteration %d\n",pthread_self(),i);
        cksem(sem_post(&s));
    }
    return NULL;
}
int main(void) {
    pthread_t t[2];
    ck(sem_init(&s,0,0));
    ck(pthread_create(&t[0],NULL,worker,NULL));
    ck(pthread_create(&t[1],NULL,worker,NULL));
    for (int i=0;i<2;i++) ck(pthread_join(t[i],NULL));
    ck(sem_destroy(&s));
    ck(pthread_mutex_destroy(&m));
    printf("done\n");
    return 0;
}
