static void ckcv(pthread_cond_t *c) { if (pthread_cond_wait(c,m)==-1) { perror("pthread_cond_wait"); exit(1); } }
static void ckcs(pthread_cond_t *c) { if (pthread_cond_signal(c)==-1) { perror("pthread_cond_signal"); exit(1); } }
static void ckcvs(pthread_cond_t *c) { if (pthread_cond_broadcast(c)==-1) { perror("pthread_cond_broadcast"); exit(1); } }
