    for(int phase=0;phase<2;phase++) {
        if(phase==0) ckmp(&m); ckcv(&cv); ckmu(&m);
        if(phase==1) ckmp(&m); ckcv(&cv2); ckmu(&m);
        printf("thread %d phase %d\n",pthread_self(),phase);
    }
    return NULL;
}
