    for(int i=0;i<4;i++) ck(pthread_create(&t[i],NULL,worker,NULL));
    for(int i=0;i<4;i++) ck(pthread_join(t[i],NULL));
    ckmp(&m); ckcvs(&cv); ckmu(&m);
    ckmp(&m); ckcvs(&cv2); ckmu(&m);
    printf("all done\n");
    return 0;
}
