Plan: Use a mutex and two condition variables to protect the counter and coordinate watchers.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
static void *counter_dec(void *p) {
    (void)p;
    int v;
    while ((v=counter) == 0) ck(pthread_cond_wait(&zero,&m));
    --counter;
    return NULL;
}
static void *watcher(void *p) {
    (void)p;
    ck(pthread_cond_wait(&zero,&m));
    assert(counter==0);
    return NULL;
}
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t zero=PTHREAD_COND_INITIALIZER;
static int counter=1;
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
int main(void) {
    pthread_t t[2];
    ck(pthread_create(&t[0],NULL,counter_dec,NULL));
    ck(pthread_create(&t[1],NULL,watcher,NULL));
    ck(pthread_join(t[0],NULL));
    ck(pthread_join(t[1],NULL));
    assert(counter==0);
    printf("counter=0\n");
    return 0;
}
```

Why it is correct: The mutex protects the counter and condition variables. The zero condition is signaled when the counter becomes zero, and any waiting watcher can reacquire the mutex and read the zero value. The counter cannot go negative because the decremented value is only used after the zero wait succeeds.

