Plan: Use one mutex to protect readcount and the resource semaphore; readers wait only for the resource when they are the first.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
static void *reader(void *p) {
    (void)p; int id=*(int *)p; for(int i=0;i<5;i++) {
        ck(pthread_mutex_lock(&rmutex)); readcount++; if(readcount==1) ck(sem_wait(&resource)); ck(pthread_mutex_unlock(&rmutex));
        ck(pthread_mutex_lock(&rmutex)); readcount--; if(readcount==0) ck(sem_post(&resource)); ck(pthread_mutex_unlock(&rmutex));
        printf("reader %d read\n",id);
    } return NULL;
}
static void *writer(void *p) {
    (void)p; int id=*(int *)p; for(int i=0;i<5;i++) {
        ck(pthread_mutex_lock(&rmutex)); writecount++; ck(pthread_mutex_unlock(&rmutex));
        ck(pthread_mutex_lock(&resource)); printf("writer %d write\n",id); ck(pthread_mutex_unlock(&resource));
        ck(pthread_mutex_lock(&rmutex)); writecount--; ck(pthread_mutex_unlock(&rmutex));
    } return NULL;
}
int main(void) {
    pthread_t t[7]; int ids[5]={0,1,2,3,4},wids[2]={5,6};
    pthread_mutexattr_t a; ck(pthread_mutexattr_init(&a)); ck(pthread_mutexattr_settype(&a,PTHREAD_MUTEX_RECURSIVE));
    pthread_mutex_t rmutex,resource; ck(pthread_mutex_init(&rmutex,&a)); ck(pthread_mutex_init(&resource,0));
    for(int i=0;i<5;i++) ck(pthread_create(&t[i],0,reader,&ids[i]));
    for(int i=0;i<2;i++) ck(pthread_create(&t[i+5],0,writer,&wids[i]));
    for(int i=0;i<7;i++) ck(pthread_join(t[i],NULL));
    ck(pthread_mutex_destroy(&rmutex)); ck(pthread_mutex_destroy(&resource)); pthread_mutexattr_destroy(&a);
    printf("done\n"); return 0;
}
```

Why it is correct: The resource semaphore protects the shared resource and is released only when the last reader leaves. The rmutex protects readcount and the entry/exit sections, so readers and writers do not race on it. The resource semaphore is not used in the writer's entry/exit sections, so it does not block a writer waiting for a reader. The finite number of threads and finite access cycles prevent indefinite waiting.

