Plan: Use four threads, each with its own partial sum and array index range, and join after all work.

```c
#define _XOPEN_SOURCE 700
#include <errno.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <assert.h>
static void *worker(void *arg) {
    int *a = *(int **)arg; int *p = a + 100000; int s = 0;
    for (int *q = a; q < p; ++q) s += *q;
    *(int *)arg = s; return NULL;
}
int main(void) {
    int a[100000]; for (int i = 0; i < 100000; ++i) a[i] = i;
    pthread_t t[4]; int s[4]; int *p[4];
    for (int i = 0; i < 4; ++i) { p[i] = &s[i]; pthread_create(&t[i], NULL, worker, p[i]); }
    for (int i = 0; i < 4; ++i) pthread_join(t[i], NULL);
    for (int i = 0; i < 4; ++i) assert(s[i] == 100000 * 100000 / 2 - 100000 * 99999 / 2);
    printf("Sum=%d\n", s[0] + s[1] + s[2] + s[3]);
    return 0;
}
```

Why it is correct: Each thread owns its own partial sum and its own array range; no shared sum is written concurrently. The join waits for each thread to complete before aggregating. The workload is finite and the join order is finite, so progress is guaranteed. The worker does not need a mutex because it does not write shared state; the main thread reads only the final partial sums after all joins.

