        ckp(&f[e]);
        ckp(&f[(e+1)%5]);
        printf("P%d eats\n",e);
        ckv(&f[(e+1)%5]);
        ckv(&f[e]);
        sleep(rand()%3);
    }
    return NULL;
}
static pthread_mutex_t m[5]={PTHREAD_MUTEX_INITIALIZER};
static sem_t f[5]={0,1,2,3,4};
static pthread_t t[5];
int main(void) {
