        ck(pthread_create(&t[e],NULL,philosopher,&e));
    }
    for (int e=0;e<5;++e) {
        ck(pthread_join(t[e],NULL));
    }
    for (int e=0;e<5;++e) {
        ck(pthread_mutex_destroy(&m[e]));
    }
    for (int e=0;e<5;++e) {
        ck(sem_destroy(&f[e]));
    }
    return 0;
}
```

Why it is correct: Each philosopher picks up the lower-indexed fork first, so the resource hierarchy avoids circular waiting. The waiter (semaphore) serializes fork acquisition, and each philosopher releases both forks before the next meal. The finite loop ensures progress.

