Plan: Use one mutex and two condition variables, one for each buffer state.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
static void ckp(sem_t *s) { if (sem_trywait(s)==-1 && errno!=EAGAIN) { fprintf(stderr,"sem error\n"); exit(1); } }
static void cks(sem_t *s) { if (sem_post(s)==-1) { fprintf(stderr,"sem error\n"); exit(1); } }
static void *producer(void *p) {
    (void)p;
    for (int i=0;i<5;i++) {
        ckp(&empty); ckp(&mutex);
        buffer[fill_ptr]=i; fill_ptr=(fill_ptr+1)%MAX;
        ckp(&mutex); cks(&full);
    } return NULL;
}
static void *consumer(void *p) {
    (void)p;
    for (int i=0;i<5;i++) {
        ckp(&full); ckp(&mutex);
        int tmp=buffer[use_ptr]; use_ptr=(use_ptr+1)%MAX;
        ckp(&mutex); cks(&empty);
        printf("got %d\n",tmp);
    } return NULL;
}
static void ckempty(void) { ckp(&empty); ckp(&mutex); ckp(&mutex); cks(&empty); }
static void ckfull(void) { ckp(&full); ckp(&mutex); ckp(&mutex); cks(&full); }
int main(void) {
    pthread_t t[2];
    sem_t empty,full;
    ck(sem_init(&empty,0,0)); ck(sem_init(&full,0,0));
    ck(pthread_mutex_init(&mutex,NULL));
    for (int i=0;i<2;i++) ck(pthread_create(&t[i],NULL,producer,NULL));
    for (int i=0;i<2;i++) ck(pthread_create(&t[i],NULL,consumer,NULL));
    for (int i=0;i<2;i++) ck(pthread_join(t[i],NULL));
    ck(sem_destroy(&empty)); ck(sem_destroy(&full)); ck(pthread_mutex_destroy(&mutex));
    return 0;
}
```

Why it is correct: The mutex protects the buffer and the count; the two condition variables signal the opposite state. A producer waits for empty and signals full; a consumer waits for full and signals empty. Each waiter holds the mutex when checking the condition, so the predicate is valid. A signal is sent only when the opposite state is available, so a consumer cannot wake an empty buffer.

