Plan: Use semaphores to protect the shared resource and track readers and writers.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
static void ckp(sem_t *s) { if (sem_trywait(s)==-1 && errno!=EAGAIN) { fprintf(stderr,"sem error\n"); exit(1); } }
static void cks(sem_t *s) { if (sem_post(s)==-1) { fprintf(stderr,"sem error\n"); exit(1); } }
static void *writer(void *p) {
    (void)p; for (int i=0;i<3;i++) { ckp(&noReaders); ckp(&noWriters); printf("write %d\n",i); cks(&noWriters); cks(&noReaders); } return NULL;
}
static void *reader(void *p) {
    (void)p; for (int i=0;i<3;i++) { ckp(&noReaders); ckp(&noWriters); printf("read %d\n",i); cks(&noReaders); } return NULL;
}
int main(void) {
    pthread_t w,r; sem_t noReaders,noWriters,readSwitch,writeSwitch;
    ck(sem_init(&noReaders,0,1)); ck(sem_init(&noWriters,0,1)); ck(sem_init(&readSwitch,0,1)); ck(sem_init(&writeSwitch,0,1));
    ck(pthread_create(&w,NULL,writer,NULL)); ck(pthread_create(&r,NULL,reader,NULL));
    ck(pthread_join(w,NULL)); ck(pthread_join(r,NULL)); ck(sem_destroy(&readSwitch)); ck(sem_destroy(&writeSwitch)); ck(sem_destroy(&noReaders)); ck(sem_destroy(&noWriters)); return 0;
}
```

Why it is correct: The entry section uses noReaders and noWriters to exclude concurrent readers and writers. The exit section releases the resource. The readSwitch semaphore is not used in this plan; its presence in the context is a hint for a different solution.

