Plan: Limit philosophers at the table with a multiplex.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
static void ckp(sem_t *s) { if (sem_trywait(s)==-1 && errno!=EAGAIN) { fprintf(stderr,"sem error\n"); exit(1); } }
static void ckv(sem_t *s) { if (sem_post(s)==-1) { fprintf(stderr,"sem error\n"); exit(1); } }
static void *eat(void *p) {
    (void)p;
    for (int i=0;i<3;i++) {
        ckp(&forks[(int)(i%5)]);
        ckp(&forks[(int)((i+1)%5)]);
        printf("eat %d\n",i);
        ckv(&forks[(int)((i+1)%5)]);
        ckv(&forks[(int)(i%5)]);
    }
    return NULL;
}
static void *think(void *p) {
    (void)p;
    for (int i=0;i<3;i++) {
        printf("think %d\n",i);
        sleep(1);
    }
    return NULL;
}
static void *diner(void *p) {
    int id=*(int *)p;
    for (int i=0;i<3;i++) {
        think(&id);
        ckp(&footman);
        ckp(&forks[(id+1)%5]);
        ckp(&forks[id]);
        printf("eat %d\n",id);
        ckv(&forks[id]);
        ckv(&forks[(id+1)%5]);
        ckv(&footman);
    }
    return NULL;
}
int main(void) {
    pthread_t t[5];
    sem_t footman, forks[5];
    for (int i=0;i<5;i++) { ck(sem_init(&forks[i],0,1)); }
    ck(sem_init(&footman,0,4));
    for (int i=0;i<5;i++) { ck(pthread_create(&t[i],NULL,diner,&i)); }
    for (int i=0;i<5;i++) { ck(pthread_join(t[i],NULL)); }
    for (int i=0;i<5;i++) { ck(sem_destroy(&forks[i])); }
    ck(sem_destroy(&footman));
    return 0;
}
```

Why it is correct: The footman multiplex limits philosophers at the table, so at most four forks are held. Each fork is protected by a mutex, and the entry section waits for both forks. The exit section releases them in reverse order. The footman semaphore is not held during fork operations, so no philosopher waits while holding it. The finite number of philosophers and finite eating cycles prevent starvation.

